/* From Uiverse.io by iSweat-exe  - Tags: simple, animation, minimalist, switch, on/off */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
  font-size: 20px;
  position: relative;
  display: inline-block;
  width: 3.5em;
  height: 2em;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #ccc;
  transition: 0.4s;
  border-radius: 10px;
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: "";
  height: 1.4em;
  width: 1.4em;
  border-radius: 5px;
  left: 0.3em;
  bottom: 0.3em;
  background-color: white;
  transition: 0.4s;
}

.__UIV_SCOPE__ .switch input:checked + .slider {
  background-color: green;
}

.__UIV_SCOPE__ .switch input:checked + .slider:before {
  transform: translateX(1.5em);
}
